function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (e) { return value; }
}

const incoming = $json;
let body = incoming.body ?? incoming;
body = parseMaybeJson(body);

let alert = body.alert ?? body;
alert = parseMaybeJson(alert);

if (alert.body) {
  const nested = parseMaybeJson(alert.body);
  if (nested && typeof nested === 'object') alert = nested.alert ?? nested;
}

let data = alert.data ?? {};
if ((!data || Object.keys(data).length === 0) && alert.full_log) {
  const parsedFullLog = parseMaybeJson(alert.full_log);
  if (parsedFullLog && typeof parsedFullLog === 'object') data = parsedFullLog;
}

const rule = alert.rule ?? {};
const agent = alert.agent ?? {};
const manager = alert.manager ?? {};
const decoder = alert.decoder ?? {};

const ruleId = Number(rule.id ?? data.expected_wazuh_rule_id ?? 0);
const ruleLevel = Number(rule.level ?? 0);
const groups = Array.isArray(rule.groups) ? rule.groups : [];

const targetRuleIds = [
  100301,100302,100303,100304,100305,100306,
  100351,100352,100353,100354,100355,100356,100357,100358,
  100401,100402,100403,100404,100405
];

// Resolve the alert domain with rule-id priority first.
// Do NOT classify on broad groups like "agentic_ai"; RAG/memory and MCP alerts can carry
// generic AI/agentic groups too, which was causing RAG/MCP events to be routed into agentic tables.
const groupsLc = groups.map(g => String(g || '').toLowerCase());
const eventSource = String(data.event_source || '').toLowerCase();

const isMcpRule = ruleId >= 100301 && ruleId <= 100306;
const isAgenticRule = ruleId >= 100351 && ruleId <= 100358;
const isRagMemoryRule = ruleId >= 100401 && ruleId <= 100405;

const mcpSpecificGroups = [
  'mcp',
  'mcp_runtime',
  'mcp_tool_poisoning',
  'mcp_schema_drift',
  'mcp_overprivileged_tool',
  'mcp_sensitive_tool_without_hitl',
  'mcp_tool_argument_injection',
  'mcp_resource_exfiltration'
];

const ragSpecificGroups = [
  'rag_memory',
  'rag_context_poisoning',
  'memory_poisoning',
  'memory_poisoning_attempt',
  'memory_scope_violation',
  'embedding_source_policy_violation',
  'unapproved_embedding_source',
  'retrieval_to_tool_escalation'
];

const agenticSpecificGroups = [
  'agent_goal_hijack',
  'agent_plan_drift_tool_chain_escalation',
  'agent_tool_loop_unbounded_consumption',
  'agent_approval_manipulation',
  'agent_identity_permission_mismatch',
  'agent_confused_deputy_multi_server',
  'agent_excessive_agency_rogue_action',
  'agent_continued_action_after_blocked_risk'
];

let alert_domain = 'unknown';

if (isMcpRule) {
  alert_domain = 'mcp';
} else if (isAgenticRule) {
  alert_domain = 'agentic';
} else if (isRagMemoryRule) {
  alert_domain = 'rag_memory';
} else if (eventSource === 'ai_demo_mcp_guardrail') {
  alert_domain = 'mcp';
} else if (eventSource === 'ai_demo_agent_guardrail') {
  alert_domain = 'agentic';
} else if (eventSource === 'ai_demo_rag_memory_guardrail') {
  alert_domain = 'rag_memory';
} else if (groupsLc.some(g => mcpSpecificGroups.includes(g))) {
  alert_domain = 'mcp';
} else if (groupsLc.some(g => ragSpecificGroups.includes(g))) {
  alert_domain = 'rag_memory';
} else if (groupsLc.some(g => agenticSpecificGroups.includes(g))) {
  alert_domain = 'agentic';
}

const isMcpEvent = alert_domain === 'mcp';
const isAgenticEvent = alert_domain === 'agentic';
const isRagMemoryEvent = alert_domain === 'rag_memory';
const isTarget = targetRuleIds.includes(ruleId) && (isMcpEvent || isRagMemoryEvent || isAgenticEvent);

return [{ json: {
  received_at: new Date().toISOString(),
  raw_alert: alert,

  rule_id: ruleId,
  rule_level: ruleLevel,
  rule_description: rule.description ?? '',
  rule_groups: groups,
  is_target_ai_mcp_alert: isTarget,
  is_target_ai_security_alert: isTarget,
  alert_domain,

  agent_id: agent.id ?? '',
  agent_name: agent.name ?? '',
  agent_ip: agent.ip ?? '',
  manager_name: manager.name ?? '',
  location: alert.location ?? '',
  decoder_name: decoder.name ?? '',

  event_source: data.event_source ?? '',
  event_type: data.event_type ?? '',
  schema_version: data.schema_version ?? '',

  request_id: data.request_id ?? '',
  session_id: data.session_id ?? '',
  user_id: data.user_id ?? '',
  agent_runtime_id: data.agent_id ?? '',
  model: data.model ?? '',
  scenario: data.scenario ?? '',
  policy_bundle_version: data.policy_bundle_version ?? '',
  policy_bundle_hash: data.policy_bundle_hash ?? '',

  // MCP fields
  mcp_server_name: data.mcp_server_name ?? '',
  mcp_server_id: data.mcp_server_id ?? '',
  server_trust_level: data.server_trust_level ?? data.mcp_server_trust_level ?? '',
  mcp_transport: data.mcp_transport ?? '',
  tool_name: data.tool_name ?? data.proposed_tool_name ?? data.target_tool_name ?? '',
  tool_category: data.tool_category ?? data.proposed_tool_category ?? '',
  tool_args_summary: data.tool_args_summary ?? data.proposed_tool_args_summary ?? '',
  tool_result_excerpt: data.tool_result_excerpt ?? '',
  tool_result_trust_level: data.tool_result_trust_level ?? '',
  resource_uri: data.resource_uri ?? '',
  resource_scope: data.resource_scope ?? '',
  resource_scope_violation: String(data.resource_scope_violation ?? ''),
  permission_scope_requested: data.permission_scope_requested ?? '',
  permission_scope_allowed: data.permission_scope_allowed ?? '',
  permission_scope_status: data.permission_scope_status ?? '',
  approval_required: data.approval_required ?? false,
  approval_status: data.approval_status ?? '',
  approval_reason: data.approval_reason ?? '',

  // RAG/memory fields
  retrieval_query: data.retrieval_query ?? '',
  retrieval_source: data.retrieval_source ?? '',
  retrieval_source_type: data.retrieval_source_type ?? '',
  source_trust_level: data.source_trust_level ?? '',
  retrieval_rank: Number(data.retrieval_rank ?? 0),
  embedding_collection: data.embedding_collection ?? '',
  embedding_source_approved: data.embedding_source_approved ?? false,
  retrieved_context_excerpt: data.retrieved_context_excerpt ?? '',
  content_risk_flags_csv: data.content_risk_flags_csv ?? '',
  memory_scope: data.memory_scope ?? '',
  memory_write_requested: data.memory_write_requested ?? false,
  memory_write_allowed: data.memory_write_allowed ?? false,
  memory_write_reason: data.memory_write_reason ?? '',
  memory_key: data.memory_key ?? '',
  memory_value_excerpt: data.memory_value_excerpt ?? '',
  proposed_tool_name: data.proposed_tool_name ?? '',
  proposed_tool_category: data.proposed_tool_category ?? '',
  proposed_tool_args_summary: data.proposed_tool_args_summary ?? '',

  // Phase 6 agentic fields
  original_user_goal: data.original_user_goal ?? '',
  observed_agent_goal: data.observed_agent_goal ?? data.current_agent_goal ?? '',
  goal_changed: data.goal_changed ?? false,
  goal_change_source: data.goal_change_source ?? '',
  agent_plan_id: data.agent_plan_id ?? '',
  agent_plan_summary: data.agent_plan_summary ?? '',
  agent_plan_step_count: Number(data.agent_plan_step_count ?? 0),
  max_allowed_plan_steps: Number(data.max_allowed_plan_steps ?? 0),
  tool_sequence_csv: data.tool_sequence_csv ?? data.tool_chain_csv ?? '',
  mcp_server_sequence_csv: data.mcp_server_sequence_csv ?? '',
  tool_call_count: Number(data.tool_call_count ?? 0),
  same_tool_repeated_count: Number(data.same_tool_repeated_count ?? 0),
  max_allowed_tool_calls: Number(data.max_allowed_tool_calls ?? 0),
  max_same_tool_repeats: Number(data.max_same_tool_repeats ?? 0),
  loop_detected: data.loop_detected ?? false,
  identity_used: data.identity_used ?? '',
  identity_scope_requested: data.identity_scope_requested ?? '',
  identity_scope_allowed: data.identity_scope_allowed ?? '',
  approval_actor: data.approval_actor ?? '',
  approval_quality: data.approval_quality ?? '',
  approval_prompt_excerpt: data.approval_prompt_excerpt ?? '',
  approval_prompt_risk_flags_csv: data.approval_prompt_risk_flags_csv ?? '',
  external_action_requested: data.external_action_requested ?? false,
  sensitive_resource_requested: data.sensitive_resource_requested ?? false,
  source_mcp_server: data.source_mcp_server ?? '',
  target_mcp_server: data.target_mcp_server ?? '',
  target_tool_name: data.target_tool_name ?? '',
  cross_server_policy_violation: data.cross_server_policy_violation ?? false,
  prior_guardrail_blocked: data.prior_guardrail_blocked ?? false,
  blocked_risk_family: data.blocked_risk_family ?? '',
  continued_after_block: data.continued_after_block ?? false,

  guardrail_action: data.guardrail_action ?? '',
  detection_family: data.detection_family ?? '',
  severity: data.severity ?? '',
  confidence: Number(data.confidence ?? 0),
  risk_score_from_event: Number(data.risk_score ?? 0),
  risk_flags_csv: data.risk_flags_csv ?? '',

  owasp_category: data.owasp_category ?? '',
  mcp_risk_category: data.mcp_risk_category ?? '',
  agentic_risk_category: data.agentic_risk_category ?? '',
  expected_wazuh_rule_id: Number(data.expected_wazuh_rule_id ?? 0)
}}];

const j = $json;

const catalog = {
  100301: { family: 'mcp_tool_poisoning', title: 'MCP tool poisoning / prompt injection via tool result', defaultRisk: 98, severity: 'critical', owasp: 'LLM01', mcpCategory: 'prompt_injection_via_tool_result', template: 'flowc-mcp-tool-poisoning', action: 'Review the tool result for hidden instructions, confirm whether the MCP server is trusted, and check whether any sensitive tool was invoked after this result.' },
  100302: { family: 'mcp_schema_drift', title: 'MCP schema or tool description drift', defaultRisk: 92, severity: 'high', owasp: 'MCP', mcpCategory: 'schema_or_description_drift', template: 'flowc-mcp-schema-drift', action: 'Compare observed tool schema and description hashes against the approved registry. Treat unexpected drift as potential tool rug-pull or supply-chain risk.' },
  100303: { family: 'mcp_overprivileged_tool', title: 'MCP over-privileged tool scope', defaultRisk: 90, severity: 'high', owasp: 'MCP', mcpCategory: 'over_privileged_tool_use', template: 'flowc-mcp-sensitive-tool-call', action: 'Review requested vs allowed permission scope and confirm whether least-privilege policy should block or narrow this tool.' },
  100304: { family: 'mcp_sensitive_tool_without_hitl', title: 'Sensitive MCP tool without HITL approval', defaultRisk: 99, severity: 'critical', owasp: 'MCP', mcpCategory: 'sensitive_tool_without_hitl', template: 'flowc-mcp-sensitive-tool-call', action: 'Confirm the approval requirement, approval status, and whether the sensitive action was blocked. Investigate missing or bypassed human-in-the-loop control.' },
  100305: { family: 'mcp_tool_argument_injection', title: 'MCP dangerous tool argument injection', defaultRisk: 94, severity: 'high', owasp: 'LLM05', mcpCategory: 'dangerous_tool_arguments', template: 'flowc-agentic-tool-misuse', action: 'Review tool arguments for shell metacharacters, command injection, external URL exfiltration, or unsafe downstream execution path.' },
  100306: { family: 'mcp_resource_exfiltration', title: 'MCP resource exfiltration or resource-root violation', defaultRisk: 99, severity: 'critical', owasp: 'MCP', mcpCategory: 'resource_exfiltration', template: 'flowc-mcp-resource-exfiltration', action: 'Validate requested resource URI against allowed roots and determine whether sensitive data access was blocked or exposed.' },

  100351: { family: 'agent_goal_hijack', title: 'Agentic goal hijack', defaultRisk: 99, severity: 'critical', owasp: 'LLM01', mcpCategory: 'none', template: 'flowc-agentic-goal-hijack', action: 'Compare original vs observed agent goal, identify the goal-change source, and confirm the risky follow-on action was blocked.' },
  100352: { family: 'agent_plan_drift_tool_chain_escalation', title: 'Agentic plan drift / tool-chain escalation', defaultRisk: 98, severity: 'critical', owasp: 'LLM01', mcpCategory: 'agentic_tool_misuse', template: 'flowc-agentic-plan-drift', action: 'Review the plan step where a low-risk goal became a high-risk tool chain; validate approval and policy blocks before any tool use.' },
  100353: { family: 'agent_tool_loop_unbounded_consumption', title: 'Agentic tool loop / unbounded consumption', defaultRisk: 88, severity: 'high', owasp: 'LLM10', mcpCategory: 'tool_loop', template: 'flowc-agentic-tool-loop', action: 'Review repeated tool count and loop thresholds; confirm the agent stopped before resource exhaustion or repeated sensitive actions.' },
  100354: { family: 'agent_approval_manipulation', title: 'Agentic approval manipulation', defaultRisk: 94, severity: 'high', owasp: 'LLM01', mcpCategory: 'human_approval_abuse', template: 'flowc-agentic-approval-bypass', action: 'Inspect the approval prompt for misleading framing, urgency pressure, and hidden data/destination fields; require a truthful approval prompt before action.' },
  100355: { family: 'agent_identity_permission_mismatch', title: 'Agent identity / permission mismatch', defaultRisk: 93, severity: 'high', owasp: 'MCP', mcpCategory: 'least_privilege_violation', template: 'flowc-agentic-identity-mismatch', action: 'Compare identity and permission scopes requested vs allowed; enforce least privilege and verify delegated identity policy.' },
  100356: { family: 'agent_confused_deputy_multi_server', title: 'Agent confused deputy across MCP servers', defaultRisk: 97, severity: 'critical', owasp: 'MCP', mcpCategory: 'confused_deputy', template: 'flowc-agentic-confused-deputy', action: 'Identify source and target MCP servers, confirm cross-server influence, and block privileged target tool invocation.' },
  100357: { family: 'agent_excessive_agency_rogue_action', title: 'Agent excessive agency / rogue action', defaultRisk: 99, severity: 'critical', owasp: 'LLM08', mcpCategory: 'excessive_agency', template: 'flowc-agentic-excessive-agency', action: 'Review autonomous high-impact action attempt and require explicit analyst approval for external send, case mutation, resource read, command mock, or memory write.' },
  100358: { family: 'agent_continued_action_after_blocked_risk', title: 'Agent continued action after blocked risk', defaultRisk: 96, severity: 'critical', owasp: 'LLM01', mcpCategory: 'guardrail_bypass_after_block', template: 'flowc-agentic-continued-after-block', action: 'Review post-block replanning and ensure the agent cannot route around a prior MCP/RAG/memory guardrail block.' },

  100401: { family: 'rag_context_poisoning', title: 'RAG untrusted context injection', defaultRisk: 96, severity: 'high', owasp: 'LLM01', mcpCategory: 'none', template: 'flowc-rag-context-poisoning', action: 'Review retrieved context, source trust level, and whether the injected content reached model context or tool planning.' },
  100402: { family: 'memory_poisoning_attempt', title: 'Memory poisoning attempt', defaultRisk: 98, severity: 'critical', owasp: 'LLM01', mcpCategory: 'none', template: 'flowc-memory-poisoning', action: 'Review memory write request, memory scope, source trust level, and confirm the poisoned memory write was blocked.' },
  100403: { family: 'memory_scope_violation', title: 'Memory scope violation', defaultRisk: 91, severity: 'high', owasp: 'LLM01', mcpCategory: 'none', template: 'flowc-memory-poisoning', action: 'Review requested memory scope and policy. Confirm user/global memory writes are blocked unless explicitly approved.' },
  100404: { family: 'unapproved_embedding_source', title: 'Unapproved RAG embedding/source registration', defaultRisk: 89, severity: 'high', owasp: 'LLM01', mcpCategory: 'none', template: 'flowc-rag-context-poisoning', action: 'Review embedding collection and source trust policy. Approve through CI/CD or block the source.' },
  100405: { family: 'retrieval_to_tool_escalation', title: 'RAG retrieval-to-tool escalation', defaultRisk: 97, severity: 'critical', owasp: 'LLM01', mcpCategory: 'retrieval_triggered_tool_misuse', template: 'flowc-rag-context-poisoning', action: 'Review retrieved context for tool-use instructions and confirm MCP/tool actions were blocked.' }
};

const meta = catalog[j.rule_id] ?? {
  family: j.detection_family || 'unknown_ai_security_family',
  title: 'AI security runtime alert',
  defaultRisk: 80,
  severity: j.severity || 'medium',
  owasp: j.owasp_category || 'MCP',
  mcpCategory: j.mcp_risk_category || 'unknown',
  template: 'flowc-mcp-generic',
  action: 'Review the AI security event, source trust, approval state, tool path, and policy decision.'
};

function resolveFlowC2Domain(j) {
  const ruleIdNum = Number(j.rule_id || 0);
  const inputDomain = String(j.alert_domain || '').toLowerCase();
  const eventSource = String(j.event_source || '').toLowerCase();
  if (ruleIdNum >= 100301 && ruleIdNum <= 100306) return 'mcp';
  if (ruleIdNum >= 100351 && ruleIdNum <= 100358) return 'agentic';
  if (ruleIdNum >= 100401 && ruleIdNum <= 100405) return 'rag_memory';
  if (eventSource === 'ai_demo_mcp_guardrail') return 'mcp';
  if (eventSource === 'ai_demo_agent_guardrail') return 'agentic';
  if (eventSource === 'ai_demo_rag_memory_guardrail') return 'rag_memory';
  if (['mcp', 'agentic', 'rag_memory'].includes(inputDomain)) return inputDomain;
  return 'mcp';
}

const riskScore = Number(j.risk_score_from_event || meta.defaultRisk || 0);
const severity = (j.severity || meta.severity || 'medium').toLowerCase();
const domain = resolveFlowC2Domain(j);
const sourcePrefix = domain === 'agentic' ? 'v2-agentic' : (domain === 'rag_memory' ? 'v2-ragmem' : 'v2-mcp');
const sourceRef = j.source_ref || `${sourcePrefix}:${j.rule_id}:${j.request_id || 'no-request-id'}`;

const dedupParts = domain === 'agentic'
  ? [sourcePrefix, j.rule_id, j.request_id || 'no-request-id', j.agent_plan_id || 'no-plan', j.detection_family || meta.family]
  : (domain === 'rag_memory'
    ? [sourcePrefix, j.rule_id, j.request_id || 'no-request-id', j.retrieval_source || 'no-source', j.memory_scope || j.embedding_collection || 'no-scope']
    : [sourcePrefix, j.rule_id, j.request_id || 'no-request-id', j.mcp_server_name || 'no-server', j.tool_name || 'no-tool']);

const dedupKey = dedupParts.join('|');

const criticalFamilies = [
  'mcp_tool_poisoning',
  'mcp_sensitive_tool_without_hitl',
  'mcp_resource_exfiltration',
  'memory_poisoning_attempt',
  'retrieval_to_tool_escalation',
  'agent_goal_hijack',
  'agent_plan_drift_tool_chain_escalation',
  'agent_confused_deputy_multi_server',
  'agent_excessive_agency_rogue_action',
  'agent_continued_action_after_blocked_risk'
];

const caseEligible =
  riskScore >= 95 ||
  criticalFamilies.includes(j.detection_family || meta.family) ||
  [100301,100304,100306,100351,100352,100356,100357,100358,100401,100402,100405].includes(j.rule_id) ||
  j.approval_status === 'missing' ||
  j.approval_status === 'bypassed' ||
  j.resource_scope_violation === 'true' ||
  (j.memory_write_allowed === false && j.memory_write_requested === true) ||
  j.continued_after_block === true ||
  j.cross_server_policy_violation === true;

const lines = [
  '*V2 AI Security Runtime Alert*', '',
  `*Rule:* ${j.rule_id} - ${meta.title}`,
  `*Severity / Risk:* ${severity.toUpperCase()} / ${riskScore}`,
  `*Domain:* ${domain}`,
  `*Detection family:* ${j.detection_family || meta.family}`,
  `*Request:* ${j.request_id || 'n/a'}`,
  `*Agent host:* ${j.agent_name || 'n/a'} (${j.agent_ip || 'n/a'})`,
  `*Agent plan:* ${j.agent_plan_id || 'n/a'} steps=${j.agent_plan_step_count || 0}`,
  `*Original goal:* ${j.original_user_goal || 'n/a'}`,
  `*Observed goal:* ${j.observed_agent_goal || 'n/a'}`,
  `*Tool sequence:* ${j.tool_sequence_csv || j.tool_name || 'n/a'}`,
  `*Server sequence:* ${j.mcp_server_sequence_csv || j.mcp_server_name || 'n/a'}`,
  `*Approval:* required=${j.approval_required} status=${j.approval_status || 'n/a'} quality=${j.approval_quality || 'n/a'}`,
  `*Identity:* ${j.identity_used || 'n/a'} requested=${j.identity_scope_requested || j.permission_scope_requested || 'n/a'} allowed=${j.identity_scope_allowed || j.permission_scope_allowed || 'n/a'}`,
  `*OWASP/MCP:* ${j.owasp_category || meta.owasp} / ${j.mcp_risk_category || meta.mcpCategory}`,
  `*Risk flags:* ${j.risk_flags_csv || j.content_risk_flags_csv || 'n/a'}`, '',
  `*Context/tool excerpt:* ${j.approval_prompt_excerpt || j.retrieved_context_excerpt || j.tool_result_excerpt || j.tool_args_summary || j.agent_plan_summary || 'n/a'}`, '',
  `*Recommended action:* ${meta.action}`,
  `*TheHive template:* ${meta.template}`,
  `*Dedup key:* ${dedupKey}`
];

return [{ json: {
  ...j,
  alert_domain: domain,
  catalog_family: meta.family,
  alert_title: `${j.rule_id} - ${meta.title}`,
  risk_score: riskScore,
  normalized_severity: severity,
  recommended_action: meta.action,
  thehive_template: meta.template,
  source_ref: sourceRef,
  dedup_key: dedupKey,
  case_promotion_eligible: caseEligible,
  slack_text: lines.join('\n')
}}];

const base = (() => {
  try { return $('Code_Build_Final_Slack_Message').first().json; } catch (e) { return {}; }
})();

const slack = $json || {};
const slackError = slack.error?.message || slack.error?.description || slack.error || slack.message?.error || '';
const slackChannel = slack.channel || slack.message?.channel || slack.data?.channel || '';
const slackTs = slack.ts || slack.message?.ts || slack.data?.ts || '';
const slackNotified = !slackError && (Boolean(slackChannel || slackTs) || Object.keys(slack).length > 0);

return [{
  json: {
    ...base,
    slack_response: slack,
    slack_notified: slackNotified,
    slack_channel: String(slackChannel || ''),
    slack_ts: String(slackTs || ''),
    slack_error: slackError ? String(slackError).slice(0, 1000) : '',
    workflow_stage: 'slack_complete_build_datatable_rows_next',
    audit_type: 'flow_c2_runtime_mcp_alert'
  }
}];

function clean(value) {
  if (value === undefined || value === null || value === '') return 'n/a';
  return String(value);
}
function truncate(value, max = 1500) {
  const text = clean(value);
  return text.length > max ? text.slice(0, max) + '...' : text;
}
function severityToHive(ruleLevel, score, severity) {
  const s = String(severity || '').toLowerCase();
  const rl = Number(ruleLevel || 0);
  const rs = Number(score || 0);
  if (s === 'critical' || rl >= 14 || rs >= 95) return 4;
  if (s === 'high' || rl >= 12 || rs >= 75) return 3;
  if (s === 'medium' || rl >= 10 || rs >= 50) return 2;
  return 1;
}
function templateFor(ruleId, family) {
  const id = Number(ruleId || 0);
  if (id === 100301 || family === 'mcp_tool_poisoning') return 'flowc-mcp-tool-poisoning';
  if (id === 100302 || family === 'mcp_schema_drift') return 'flowc-mcp-schema-drift';
  if ([100303,100304].includes(id) || ['mcp_overprivileged_tool','mcp_sensitive_tool_without_hitl'].includes(family)) return 'flowc-mcp-sensitive-tool-call';
  if (id === 100306 || family === 'mcp_resource_exfiltration') return 'flowc-mcp-resource-exfiltration';
  if (id === 100305 || family === 'mcp_tool_argument_injection') return 'flowc-agentic-tool-misuse';
  if (id === 100351 || family === 'agent_goal_hijack') return 'flowc-agentic-goal-hijack';
  if (id === 100352 || family === 'agent_plan_drift_tool_chain_escalation') return 'flowc-agentic-plan-drift';
  if (id === 100353 || family === 'agent_tool_loop_unbounded_consumption') return 'flowc-agentic-tool-loop';
  if (id === 100354 || family === 'agent_approval_manipulation') return 'flowc-agentic-approval-bypass';
  if (id === 100355 || family === 'agent_identity_permission_mismatch') return 'flowc-agentic-identity-mismatch';
  if (id === 100356 || family === 'agent_confused_deputy_multi_server') return 'flowc-agentic-confused-deputy';
  if (id === 100357 || family === 'agent_excessive_agency_rogue_action') return 'flowc-agentic-excessive-agency';
