const title = j.alert_title || `${j.rule_id || 'n/a'} - ${j.detection_family || 'AI security alert'}`;

const mcpSummary = compact([
  `MCP server ${clean(j.mcp_server_name)} [${clean(j.server_trust_level)}]`,
  `tool ${clean(j.tool_name)}`,
  `guardrail=${clean(j.guardrail_action)}`,
  `approval=${clean(j.approval_status)}`,
  `resource_violation=${clean(j.resource_scope_violation)}`
]);

const ragSummary = compact([
  `source ${clean(j.retrieval_source)} [${clean(j.source_trust_level)}]`,
  `embedding=${clean(j.embedding_collection)} approved=${clean(j.embedding_source_approved)}`,
  `memory=${clean(j.memory_scope)} requested=${clean(j.memory_write_requested)} allowed=${clean(j.memory_write_allowed)}`,
  `guardrail=${clean(j.guardrail_action)}`
]);

const agenticSummary = compact([
  `goal ${trunc(j.original_user_goal, 120)} -> ${trunc(j.observed_agent_goal, 120)}`,
  `plan=${clean(j.agent_plan_id)} steps=${clean(j.agent_plan_step_count)}`,
  `tools=${trunc(j.tool_sequence_csv, 180)}`,
  `approval=${clean(j.approval_status)} quality=${clean(j.approval_quality)}`,
  `identity=${clean(j.identity_used)}`,
  `guardrail=${clean(j.guardrail_action)}`
]);

const common = [
  `:rotating_light: *Flow C2 AI Alert: ${title}*`,
  `*Summary:* ${isAgentic ? agenticSummary : (isRag ? ragSummary : mcpSummary)}`,
  `*Rule:* ${clean(j.rule_id)} | *Level:* ${clean(j.rule_level)} | *Score:* ${riskScore} | *Severity:* ${severity}`,
  `*Domain:* ${clean(j.alert_domain)}`,
  `*Detection family:* ${clean(j.detection_family || j.catalog_family)}`,
  `*OWASP/MCP:* ${clean(j.owasp_category)} / ${clean(j.mcp_risk_category)}`,
  `*Agentic risk:* ${clean(j.agentic_risk_category)}`,
  `*Request:* ${clean(j.request_id)} | *Session:* ${clean(j.session_id)} | *User:* ${clean(j.user_id)}`,
  `*Agent:* ${clean(j.agent_name)}${j.agent_ip ? ' (' + j.agent_ip + ')' : ''} | *Location:* ${clean(j.location)}`,
];

const mcpLines = [
  `*MCP server:* ${clean(j.mcp_server_name)} [${clean(j.server_trust_level)}] | *Transport:* ${clean(j.mcp_transport)}`,
  `*Tool:* ${clean(j.tool_name)} (${clean(j.tool_category)})`,
  `*Approval:* required=${clean(j.approval_required)} status=${clean(j.approval_status)}`,
  `*Permission:* requested=${clean(j.permission_scope_requested)} allowed=${clean(j.permission_scope_allowed)} status=${clean(j.permission_scope_status)}`,
  `*Resource:* ${clean(j.resource_uri)} violation=${clean(j.resource_scope_violation)}`,
  `*Tool args:* ${trunc(j.tool_args_summary, 500)}`,
  `*Tool result excerpt:* ${trunc(j.tool_result_excerpt, 750)}`,
];

const ragLines = [
  `*Retrieval source:* ${clean(j.retrieval_source)} [${clean(j.source_trust_level)}]`,
  `*Retrieval query:* ${trunc(j.retrieval_query, 500)}`,
  `*Embedding:* ${clean(j.embedding_collection)} approved=${clean(j.embedding_source_approved)}`,
  `*Content risk flags:* ${clean(j.content_risk_flags_csv)}`,
  `*Memory:* scope=${clean(j.memory_scope)} requested=${clean(j.memory_write_requested)} allowed=${clean(j.memory_write_allowed)}`,
  `*Memory reason:* ${trunc(j.memory_write_reason, 500)}`,
  `*Proposed tool:* ${clean(j.proposed_tool_name)} (${clean(j.proposed_tool_category)})`,
  `*Proposed tool args:* ${trunc(j.proposed_tool_args_summary, 500)}`,
  `*Retrieved context excerpt:* ${trunc(j.retrieved_context_excerpt, 800)}`,
];

const agenticLines = [
  `*Original goal:* ${trunc(j.original_user_goal, 500)}`,
  `*Observed goal:* ${trunc(j.observed_agent_goal, 500)}`,
  `*Goal changed:* ${clean(j.goal_changed)} via ${clean(j.goal_change_source)}`,
  `*Plan:* ${clean(j.agent_plan_id)} | steps=${clean(j.agent_plan_step_count)} max=${clean(j.max_allowed_plan_steps)}`,
  `*Plan summary:* ${trunc(j.agent_plan_summary, 700)}`,
  `*Tool sequence:* ${trunc(j.tool_sequence_csv, 700)}`,
  `*MCP server sequence:* ${trunc(j.mcp_server_sequence_csv, 500)}`,
  `*Loop counters:* total_calls=${clean(j.tool_call_count)} same_tool_repeats=${clean(j.same_tool_repeated_count)} loop=${clean(j.loop_detected)}`,
  `*Identity:* ${clean(j.identity_used)} | requested=${clean(j.identity_scope_requested || j.permission_scope_requested)} | allowed=${clean(j.identity_scope_allowed || j.permission_scope_allowed)} | status=${clean(j.permission_scope_status)}`,
  `*Approval:* required=${clean(j.approval_required)} status=${clean(j.approval_status)} quality=${clean(j.approval_quality)}`,
  `*Approval prompt flags:* ${clean(j.approval_prompt_risk_flags_csv)}`,
  `*Cross-server:* ${clean(j.source_mcp_server)} -> ${clean(j.target_mcp_server)} / ${clean(j.target_tool_name)} violation=${clean(j.cross_server_policy_violation)}`,
  `*Post-block:* prior=${clean(j.prior_guardrail_blocked)} family=${clean(j.blocked_risk_family)} continued=${clean(j.continued_after_block)}`,
  `*External/sensitive:* external_action=${clean(j.external_action_requested)} sensitive_resource=${clean(j.sensitive_resource_requested)}`,
];

const baseMessage = [
  ...common,
  ...(isAgentic ? agenticLines : (isRag ? ragLines : mcpLines)),
  `*Guardrail action:* ${clean(j.guardrail_action)}`,
  `*Risk flags:* ${clean(j.risk_flags_csv || j.content_risk_flags_csv)}`,
  `*Recommended action:* ${clean(j.recommended_action)}`,
  `*Dedup:* ${clean(j.dedup_key)}`
].join('\n');

const slackText = `${baseMessage}\n${theHiveFooter(j)}`;

return [{ json: { ...j, slack_text_final: slackText, slack_text: slackText, workflow_stage: 'final_slack_message_built' } }];
